// ─── File: src/test/java/com/bank/spliterator/SpliteratorTest.java ───
package com.bank.spliterator;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class SpliteratorTest {

    @Test
    void tryAdvance_processesOneElement() {
        List<String> accounts = List.of("SAV2001", "CUR3001");
        Spliterator<String> sp = accounts.spliterator();
        List<String> processed = new ArrayList<>();

        assertThat(sp.tryAdvance(processed::add)).isTrue();
        assertThat(sp.tryAdvance(processed::add)).isTrue();
        assertThat(sp.tryAdvance(processed::add)).isFalse();  // exhausted!
        assertThat(processed).containsExactly("SAV2001", "CUR3001");
    }

    @Test
    void trySplit_divideData() {
        List<Integer> data = new ArrayList<>();
        for (int i = 0; i < 100; i++) data.add(i);

        Spliterator<Integer> original = data.spliterator();
        Spliterator<Integer> firstHalf = original.trySplit();  // splits!

        assertThat(firstHalf).isNotNull();
        // firstHalf + original together cover all 100 elements
        long firstSize = firstHalf.estimateSize();
        long secondSize = original.estimateSize();
        assertThat(firstSize + secondSize).isEqualTo(100);
    }

    @Test
    void estimateSize_and_characteristics() {
        List<String> list = List.of("A", "B", "C");
        Spliterator<String> sp = list.spliterator();

        assertThat(sp.estimateSize()).isEqualTo(3);
        assertThat(sp.hasCharacteristics(Spliterator.ORDERED)).isTrue();
        assertThat(sp.hasCharacteristics(Spliterator.SIZED)).isTrue();
    }

    @Test
    void forEachRemaining_processAll() {
        Spliterator<String> sp = List.of("SAV2001", "CUR3001", "FD4001").spliterator();
        List<String> all = new ArrayList<>();
        sp.forEachRemaining(all::add);
        assertThat(all).containsExactly("SAV2001", "CUR3001", "FD4001");
    }
}
